#!/bin/bash
# the S5 bench (from S4's): ONE page (test&scene=12, the fake), q pinned, 8 s warm, a cold call discarded, then 3 interleaved quads of the SUBSTRATE
# benchFluid(300,null,'pool') / bands ship (K2 default: the pen on, AX 1, V 0) / bands with the pen OFF (PEN_SRC 0: the floor's splat) / bands with the
# pen pushing (PEN_V 1: the splat's velocity set) — the pen is one splat for one splat, so the quads must sit within ±.05; then MOBILE=1 tier 0 alive + the quads
cd /home/toma/Documents/Kraftek/RetinaRave-wt-fluid2 || exit 1
E='{"eval":"CARD.benchFluid(300,null,\"pool\").toFixed(3)+\" pool\""},{"eval":"(CARD.fluid.K2.PEN_SRC=1,CARD.fluid.K2.PEN_V=0,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" ship \"+JSON.stringify(CARD.fluid.pen))"},{"eval":"(CARD.fluid.K2.PEN_SRC=0,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" pen-off \"+JSON.stringify(CARD.fluid.pen))"},{"eval":"(CARD.fluid.K2.PEN_SRC=1,CARD.fluid.K2.PEN_V=1,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" pen-v1\")"}'
GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=12" "[{\"until\":\"window.CARD\"},{\"eval\":\"setInterval(()=>CARD.Q.q=0.95,16);'pinned'\"},{\"wait\":8000},{\"eval\":\"CARD.benchFluid(300,null,'pool').toFixed(3)+' cold'\"},$E,$E,$E,{\"eval\":\"(CARD.fluid.K2.PEN_V=0,CARD.bench(13,300).toFixed(3)+' show13')\"},{\"eval\":\"CARD.bench(12,300).toFixed(3)+' show12'\"},{\"eval\":\"CARD.bench(0,300).toFixed(3)+' nav'\"},{\"eval\":\"JSON.stringify({tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],q:CARD.Q.q,g:CARD.fluid.grammar,errs:CARD.ERRS})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
uptime
echo "== MOBILE=1 tier 0: scene 13 alive + the substrate quads at tier 0"
MOBILE=1 GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=13" "[{\"until\":\"window.CARD\"},{\"wait\":4000},{\"eval\":\"JSON.stringify({sc:CARD.SC.cur,g:CARD.fluid.grammar,tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],errs:CARD.ERRS,bad:CARD.nonFinite(),frameN:CARD.frameN,pen:CARD.fluid.pen,flinfo:CARD.REG[13].scene.hooks.flinfo()})\"},{\"eval\":\"CARD.benchFluid(300,null,'bands').toFixed(3)+' bands ship'\"},{\"eval\":\"(CARD.fluid.K2.PEN_SRC=0,CARD.benchFluid(300,null,'bands').toFixed(3)+' bands pen-off')\"},{\"eval\":\"(CARD.fluid.K2.PEN_SRC=1,CARD.benchFluid(300,null,'pool').toFixed(3)+' pool')\"},{\"eval\":\"CARD.bench(13,300).toFixed(3)+' show13'\"},{\"eval\":\"CARD.bench(12,300).toFixed(3)+' show12'\"},{\"shot\":\"s5-mobile-s13\"},{\"eval\":\"JSON.stringify({errs:CARD.ERRS,bad:CARD.nonFinite(),tier:CARD.fluid.tier,pen:CARD.fluid.pen})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
